function New-WinOptimizerRestorePoint {Show-Header;Write-Host "CRIAR PONTO DE RESTAURACAO" -ForegroundColor Yellow;if(-not(Confirm-WinOptimizerAction "Deseja criar um ponto de restauracao?")){return};try{Enable-ComputerRestore -Drive "$env:SystemDrive\" -ErrorAction SilentlyContinue;Checkpoint-Computer -Description "WinOptimizer - $((Get-Date).ToString('yyyy-MM-dd HH-mm'))" -RestorePointType MODIFY_SETTINGS;Write-Status "Ponto de restauracao criado ou solicitado." Green;Save-AppliedChange Backup "Ponto de restauracao" "Criado antes de alteracoes."}catch{Write-Status "Nao foi possivel criar o ponto. A Protecao do Sistema pode estar desativada ou limitada a 24h." Yellow;Write-Log $_.Exception.Message ERROR};Pause-WinOptimizer}
function New-WinOptimizerBackup {Show-Header;Write-Host "BACKUP DE REGISTRO E ESTADO" -ForegroundColor Yellow;if(-not(Confirm-WinOptimizerAction "Deseja criar backup?")){return};$folder=Join-Path $script:WinOptimizerBackupFolder ("Backup-"+(Get-Date -Format "yyyyMMdd-HHmmss"));New-Item $folder -ItemType Directory -Force|Out-Null;try{$keys=@("HKLM\SOFTWARE\Policies\Microsoft\Windows\DataCollection","HKLM\SOFTWARE\Policies\Microsoft\Windows\CloudContent","HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo","HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager","HKLM\SOFTWARE\Policies\Microsoft\Windows\System");$n=0;foreach($key in $keys){$n++;reg.exe export $key (Join-Path $folder "registry-$n.reg") /y|Out-Null};Get-Service DiagTrack,dmwappushservice,WerSvc,XblAuthManager,XblGameSave,XboxNetApiSvc,XboxGipSvc -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType|ConvertTo-Json|Set-Content (Join-Path $folder "services.json");[PSCustomObject]@{Created=(Get-Date);Folder=$folder;Computer=$env:COMPUTERNAME}|ConvertTo-Json|Set-Content (Join-Path $folder "backup-info.json");Write-Status "Backup criado em: $folder" Green;Save-AppliedChange Backup "Backup completo" $folder}catch{Write-Status "Backup parcial. Algumas chaves podem nao existir." Yellow;Write-Log $_.Exception.Message ERROR};Pause-WinOptimizer}
